import type { IncomingMessage, ServerResponse } from 'http';
// Load the esbuild bundle, not the TypeScript source tree. Unbundled firebase-admin pulls
// jwks-rsa which require()s ESM-only jose and crashes Node 22 (ERR_REQUIRE_ESM).
// @ts-ignore - generated by `npm run build`
import { handleCoreApi } from '../core-server.bundle.js';

// Meta signs the exact raw bytes, so Vercel must not parse the body.
export const config = { api: { bodyParser: false } };

export default async function handler(req: IncomingMessage & { body?: any; rawBody?: Buffer }, res: ServerResponse) {
  try {
    if (req.method === 'POST') {
      const chunks: Buffer[] = [];
      for await (const chunk of req) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
      const rawBody = Buffer.concat(chunks);
      req.rawBody = rawBody;
      try {
        req.body = JSON.parse(rawBody.toString('utf8'));
      } catch {
        res.statusCode = 400;
        res.setHeader('Content-Type', 'application/json');
        return res.end(JSON.stringify({ error: 'Invalid JSON webhook payload.' }));
      }
    }
    // The bundled router matches the public path.
    req.url = '/api/webhooks/instagram' + (req.url?.includes('?') ? req.url.slice(req.url.indexOf('?')) : '');
    const handled = await handleCoreApi(req, res);
    if (!handled && !res.writableEnded) {
      res.statusCode = 404;
      res.end();
    }
  } catch (error: any) {
    console.error('[Instagram webhook] Handler failed:', error?.message || 'unknown error');
    if (!res.writableEnded) {
      res.statusCode = 500;
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ error: 'Instagram webhook processing failed.' }));
    }
  }
}
